-- | Build identity (hogd/version.h).  Regenerated by gen-xdr.sh from the
-- protocol submodule's commit.
module Hogd.Version
  ( hogdVersion
  , protocolCommit
  , protocolToken
  ) where

import qualified Data.ByteString.Char8 as BC

hogdVersion :: String
hogdVersion = "hog_exec_hs-0.1.0"

protocolCommit :: String
protocolCommit = "a67b703a554a9cabbd01b7b5a70e26383ecefab0"

-- | The 20-byte protocol token peers compare at intro: "hogp/" followed by
-- the leading characters of the protocol commit, padded with '_'.
protocolToken :: BC.ByteString
protocolToken = BC.take 20 (BC.pack ("hogp/" ++ protocolCommit) <> BC.replicate 20 '_')
